<script setup lang="ts">
import {ref,computed,watch,nextTick,onUnmounted} from 'vue';
import {native} from '../../packages/shared/client';
import {ArrowLeft,Box,Play,Square,FolderOpen,FileText,Trash2,Pencil,Save,RefreshCw,Search,Plus,X,Terminal,Settings,Package,RotateCcw,Coffee,Copy,ChevronRight,ShieldCheck} from '../../packages/ui/icons';
const props=withDefaults(defineProps<{instance:any,jobs:any[],accountReady?:boolean,parentBusy?:boolean}>(),{accountReady:false,parentBusy:false});
const emit=defineEmits(['back','play','stop','account','refresh','browse-mods']);
const tab=ref('overview'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const path=ref(''),entries=ref<any[]>([]),mods=ref<any[]>([]),trash=ref<any[]>([]),backups=ref<any[]>([]),query=ref(''),modFilter=ref('all');
const editor=ref<any>(null),text=ref(''),consoleText=ref(''),liveLogs=ref(true),modInput=ref<HTMLInputElement|null>(null);
const form=ref({name:'',memory:4096,javaPath:'auto'});
const dialog=ref<string|null>(null),dialogElement=ref<HTMLDialogElement|null>(null),dialogName=ref(''),selected=ref<any>(null);
let leaveAnswer:((value:boolean)=>void)|null=null;let logTimer:ReturnType<typeof setInterval>|null=null;
const dirty=computed(()=>!!editor.value&&text.value!==editor.value.content);
const task=computed(()=>props.jobs.find(j=>j.instanceId===props.instance.id&&['queued','running'].includes(j.status)));
const locked=computed(()=>busy.value||props.parentBusy||props.instance.running||!!task.value);
const visibleFiles=computed(()=>entries.value.filter(f=>f.name.toLowerCase().includes(query.value.toLowerCase())));
const visibleMods=computed(()=>mods.value.filter(m=>(modFilter.value==='all'||(modFilter.value==='enabled'&&m.enabled)||(modFilter.value==='disabled'&&!m.enabled)||(modFilter.value==='problems'&&m.issue))&&`${m.name} ${m.modId||''} ${m.version||''}`.toLowerCase().includes(query.value.toLowerCase())));
const crumbs=computed(()=>path.value?path.value.split('/').map((name,i,parts)=>({name,path:parts.slice(0,i+1).join('/')})):[]);
const tabs=[{id:'overview',name:'Overview',icon:Box},{id:'mods',name:'Mods',icon:Package},{id:'files',name:'Files',icon:FolderOpen},{id:'backups',name:'Backups',icon:ShieldCheck},{id:'logs',name:'Logs',icon:Terminal},{id:'trash',name:'Trash',icon:Trash2},{id:'settings',name:'Settings',icon:Settings}];
const bytes=(n:number)=>n>=1048576?`${(n/1048576).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n} B`;
const edited=(name:string)=>/\.(txt|json|json5|toml|yaml|yml|properties|log|cfg|ini|conf|md|csv|xml|mcmeta)$/i.test(name);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function readTab(){loading.value=true;error.value='';try{
 if(tab.value==='files')entries.value=await native('instance_files',{id:props.instance.id,path:path.value});
 if(tab.value==='mods')mods.value=await native('instance_mods',{id:props.instance.id});
 if(tab.value==='backups')backups.value=await native('instance_backups',{id:props.instance.id});
 if(tab.value==='trash')trash.value=await native('instance_trash',{id:props.instance.id});
 if(tab.value==='logs')await refreshLogs();
}catch(e){error.value=String(e)}finally{loading.value=false}}
async function refreshLogs(){try{consoleText.value=await native('instance_logs',{id:props.instance.id})}catch{consoleText.value='No game log yet. Start this instance to see its output.'}}
async function canLeave(){if(!dirty.value)return true;dialog.value='discard';return new Promise<boolean>(resolve=>{leaveAnswer=resolve})}
defineExpose({canLeave});
function dismiss(){if(leaveAnswer){leaveAnswer(false);leaveAnswer=null}error.value='';dialog.value=null}
async function selectTab(value:string){if(!await canLeave())return;editor.value=null;tab.value=value;query.value='';await readTab()}
async function back(){if(await canLeave())emit('back')}
async function openFolder(value:string){if(!await canLeave())return;editor.value=null;path.value=value;tab.value='files';query.value='';await readTab()}
async function openFile(entry:any){if(entry.directory){await openFolder(entry.path);return}if(!edited(entry.name)){selected.value=entry;dialog.value='details';return}await run(async()=>{if(!await canLeave())return;editor.value=await native('instance_text',{id:props.instance.id,path:entry.path});text.value=editor.value.content})}
async function save(){await run(async()=>{const result=await native('instance_file_action',{id:props.instance.id,action:'save',path:editor.value.path,content:text.value,expectedSha256:editor.value.sha256});editor.value={...editor.value,content:text.value,sha256:result.sha256};notice.value='Saved on this device.'})}
function formatJson(){try{text.value=JSON.stringify(JSON.parse(text.value),null,2)+'\n';error.value=''}catch{error.value='This JSON has a syntax error. Fix it before formatting.'}}
function ask(kind:string,entry?:any){error.value='';selected.value=entry||null;dialogName.value=kind==='rename'?entry.name:kind==='new-backup'?`${props.instance.name} backup`:'';dialog.value=kind}
async function confirm(){
 if(dialog.value==='discard'){editor.value=null;dialog.value=null;leaveAnswer?.(true);leaveAnswer=null;return}
 await run(async()=>{const action=dialog.value;const id=props.instance.id;
  if(action==='new-folder'||action==='new-file'){
   const name=dialogName.value.trim();if(!name||name.includes('/')||name.includes('\\'))throw Error('Enter a single file or folder name.');const target=path.value?`${path.value}/${name}`:name;
   await native('instance_file_action',{id,action:action==='new-folder'?'mkdir':'save',path:target,content:action==='new-file'&&/\.(json|mcmeta)$/i.test(name)?'{}\n':''});
  }
  if(action==='rename'){const name=dialogName.value.trim();if(!name||name.includes('/')||name.includes('\\'))throw Error('Enter a single name.');const parent=selected.value.path.split('/').slice(0,-1).join('/');await native('instance_file_action',{id,action:'rename',path:selected.value.path,target:parent?`${parent}/${name}`:name})}
  if(action==='trash')await native('instance_file_action',{id,action:'trash',path:selected.value.path});
  if(action==='new-backup'){const name=dialogName.value.trim();if(!name)throw Error('Enter a backup name.');await native('instance_backup_action',{id,action:'create',name})}
  if(action==='restore-backup')await native('instance_backup_action',{id,action:'restore',backupId:selected.value.id});
  if(action==='delete-backup')await native('instance_backup_action',{id,action:'delete',backupId:selected.value.id});
  dialog.value=null;await readTab();notice.value=action==='trash'?'Moved to Trash. You can restore it later.':action==='new-backup'?'Backup saved on this device.':action==='restore-backup'?'Backup restored to this instance.':action==='delete-backup'?'Backup deleted.':'Done.';
 })
}
async function importModFile(event:Event){
 const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;
 await run(async()=>{
  if(!file.name.toLowerCase().endsWith('.jar'))throw Error('Choose a valid .jar mod file.');
  if(!file.size||file.size>128*1024*1024)throw Error('Choose a .jar mod file up to 128 MiB.');
  const buf=new Uint8Array(await file.arrayBuffer());let binary='';const chunk=0x8000;
  for(let i=0;i<buf.length;i+=chunk)binary+=String.fromCharCode(...buf.subarray(i,i+chunk));
  await native('import_instance_mod',{id:props.instance.id,fileName:file.name,bytesBase64:btoa(binary)});
  await readTab();notice.value=`Imported ${file.name}.`;
 });
}
async function restore(entry:any){await run(async()=>{await native('instance_file_action',{id:props.instance.id,action:'restore',path:entry.id});await readTab();notice.value='Restored to its original folder.'})}
async function toggle(mod:any){await run(async()=>{await native('toggle_instance_mod',{id:props.instance.id,path:mod.path,enabled:!mod.enabled});await readTab()})}
async function saveSettings(){await run(async()=>{await native('edit_instance',{id:props.instance.id,...form.value});notice.value='Instance settings saved.';emit('refresh')})}
async function copy(value:string){try{await navigator.clipboard.writeText(value);notice.value='Copied.'}catch{error.value='Clipboard is unavailable. Select the text and copy it manually.'}}
async function cancelTask(){try{await native('download_action',{id:task.value.id,action:'cancel'});notice.value='Cancelling…';emit('refresh')}catch(e){error.value=String(e)}}
watch(()=>props.instance.id,()=>{tab.value='overview';path.value='';entries.value=[];mods.value=[];backups.value=[];trash.value=[];consoleText.value='';query.value='';editor.value=null;error.value='';notice.value='';form.value={name:props.instance.name,memory:props.instance.memory||4096,javaPath:props.instance.javaPath||'auto'}},{immediate:true});
watch(dialog,async value=>{await nextTick();if(value&&!dialogElement.value?.open)dialogElement.value?.showModal();if(!value&&dialogElement.value?.open)dialogElement.value.close()});
watch(()=>[tab.value,props.instance.running,liveLogs.value],()=>{if(logTimer)clearInterval(logTimer);logTimer=null;if(tab.value==='logs'&&props.instance.running&&liveLogs.value)logTimer=setInterval(()=>void refreshLogs(),2000)});
onUnmounted(()=>{if(logTimer)clearInterval(logTimer);leaveAnswer?.(false)});
</script>

<template>
<section class="instance-workspace">
 <button class="workspace-back" @click="back"><ArrowLeft :size="16"/> Your library</button>
 <header class="workspace-heading"><div class="instance-monogram">{{instance.name.slice(0,1).toUpperCase()}}</div><div class="workspace-identity"><span class="workspace-kicker">YOUR INSTANCE</span><h1>{{instance.name}}</h1><div class="workspace-tags"><span>{{instance.gameVersion}}</span><span>{{instance.loader}}{{instance.loaderVersion?' '+instance.loaderVersion:''}}</span><span :class="{running:instance.running}">{{instance.running?'Running':instance.state}}</span></div></div><div class="workspace-primary-actions"><button title="Open instance folder" @click="run(async()=>{await native('open_instance_folder',{id:instance.id})})"><FolderOpen/><span>Open folder</span></button><button v-if="instance.running" class="workspace-play stop" :disabled="busy||parentBusy" @click="emit('stop',instance)"><Square/> Stop game</button><button v-else-if="!accountReady" class="workspace-play" :disabled="busy||parentBusy||!!task" @click="emit('account')"><Plus/> Add Minecraft account</button><button v-else class="workspace-play" :disabled="busy||parentBusy||!!task||instance.state!=='installed'" @click="emit('play',instance)"><Play/> Play</button></div></header>
 <div v-if="task" class="workspace-task"><Coffee/><div><strong>{{task.detail||'Preparing your instance…'}}</strong><span v-if="task.total">{{bytes(task.downloaded)}} / {{bytes(task.total)}}</span><progress v-if="task.total" :value="task.downloaded" :max="task.total"/><div v-else class="workspace-indeterminate"/></div><button @click="cancelTask">Cancel</button></div>
 <nav class="workspace-tabs" aria-label="Instance pages"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="selectTab(item.id)"><component :is="item.icon" :size="17"/>{{item.name}}<span v-if="item.id==='mods'&&mods.length">{{mods.length}}</span><span v-if="item.id==='backups'&&backups.length">{{backups.length}}</span></button></nav>
 <p v-if="error" class="workspace-message problem" role="alert">{{error}}</p><p v-if="notice" class="workspace-message" role="status">{{notice}}</p>
 <div v-if="tab==='overview'" class="workspace-overview"><section><span class="workspace-kicker">THE BASICS</span><h2>Make this one yours.</h2><p>Your game files, settings and saves stay together in this instance.</p><dl class="workspace-facts"><div><dt>Minecraft</dt><dd>{{instance.gameVersion}}</dd></div><div><dt>Loader</dt><dd>{{instance.loader}}{{instance.loaderVersion?' '+instance.loaderVersion:''}}</dd></div><div><dt>Memory</dt><dd>{{instance.memory||4096}} MiB</dd></div><div><dt>Java</dt><dd>{{['auto','java'].includes(instance.javaPath||'auto')?'Automatic setup':instance.javaPath}}</dd></div></dl></section><section class="workspace-shortcuts"><span class="workspace-kicker">QUICK ACCESS</span><button @click="selectTab('mods')"><Package/><div><strong>Manage your mods</strong><span>See versions, import .jar files, or enable and disable mods.</span></div><ChevronRight/></button><button @click="openFolder('')"><FolderOpen/><div><strong>Browse instance files</strong><span>Edit configs and keep your folders tidy.</span></div><ChevronRight/></button><button @click="selectTab('backups')"><ShieldCheck/><div><strong>World &amp; config backups</strong><span>Save or restore snapshots of your worlds and settings.</span></div><ChevronRight/></button><button @click="selectTab('logs')"><Terminal/><div><strong>Read game logs</strong><span>See what happened when the game started.</span></div><ChevronRight/></button><button @click="selectTab('trash')"><RotateCcw/><div><strong>Restore removed files</strong><span>Deleted here means moved to Trash.</span></div><ChevronRight/></button></section></div>
 <template v-if="tab==='mods'"><div class="workspace-section-heading"><div><h2>Your mods <span>{{mods.length}}</span></h2><p>These are the actual files in this instance's mods folder.</p></div><div class="row"><input ref="modInput" type="file" accept=".jar,application/java-archive" aria-label="Import mod .jar file" hidden @change="importModFile"><button :disabled="locked||instance.loader==='vanilla'" @click="modInput?.click()"><Plus/> Add .jar file</button><button @click="emit('browse-mods')"><Search/> Find mods</button></div></div><p v-if="instance.loader==='vanilla'" class="workspace-message">Vanilla does not load mods. Use a Fabric, Quilt or other modded instance for them.</p><div class="workspace-tools"><label class="workspace-search"><Search/><input v-model="query" aria-label="Search installed mods" placeholder="Find a mod by name or version…"></label><select v-model="modFilter" aria-label="Mod state filter"><option value="all">All mods</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option><option value="problems">Needs attention</option></select><button title="Refresh mods" :disabled="loading" @click="readTab"><RefreshCw/></button></div><div v-if="loading" class="workspace-empty">Reading mod files…</div><div v-else-if="!visibleMods.length" class="workspace-empty"><Package/><h3>{{mods.length?'No mods match':'No mods here yet'}}</h3><p>{{mods.length?'Try another search or filter.':'Import a .jar file or find compatible content for this instance.'}}</p><button @click="openFolder('')">Browse instance files</button></div><div v-else class="workspace-file-list"><article v-for="mod in visibleMods" :key="mod.path" class="workspace-mod-row" :class="{disabled:!mod.enabled}"><span class="workspace-file-symbol"><Package/></span><div class="workspace-row-name"><strong>{{mod.name}}</strong><span>{{mod.version||'Version not provided'}} · {{mod.loaders.join(', ')||'Loader unknown'}}<template v-if="mod.issue"> · {{mod.issue}}</template></span><small>{{mod.fileName}}</small></div><span class="workspace-file-size">{{bytes(mod.size)}}</span><button role="switch" :aria-checked="mod.enabled" :aria-label="(mod.enabled?'Disable ':'Enable ')+mod.name" :disabled="locked" class="workspace-switch" @click="toggle(mod)"><i/></button><button :aria-label="'Move '+mod.name+' to Trash'" :disabled="locked" class="workspace-icon-button" @click="ask('trash',{...mod,name:mod.fileName})"><Trash2/></button></article></div></template>
 <template v-if="tab==='files'"><div class="workspace-section-heading"><div><h2>Instance files</h2><p>Only files inside this instance. Saves stay separate from game updates.</p></div><div class="row"><button :disabled="locked" @click="ask('new-folder')"><Plus/> Folder</button><button :disabled="locked" @click="ask('new-file')"><FileText/> Text file</button></div></div><div class="workspace-tools"><div class="workspace-breadcrumb"><button @click="openFolder('')">Files</button><template v-for="crumb in crumbs" :key="crumb.path"><ChevronRight :size="13"/><button @click="openFolder(crumb.path)">{{crumb.name}}</button></template></div><button title="Refresh files" :disabled="loading||dirty" @click="readTab"><RefreshCw/></button></div><template v-if="editor"><div class="workspace-editor-bar"><span><FileText/>{{editor.path}} <em v-if="dirty">Unsaved</em></span><div class="row"><button v-if="/\.(json|mcmeta)$/i.test(editor.path)" :disabled="locked" @click="formatJson">Format JSON</button><button :disabled="locked||!dirty" @click="save"><Save/> Save</button><button aria-label="Close file editor" @click="canLeave().then(ok=>{if(ok)editor=null})"><X/></button></div></div><textarea v-model="text" class="workspace-editor" aria-label="File contents" spellcheck="false" :readonly="locked"/></template><template v-else><label class="workspace-search"><Search/><input v-model="query" aria-label="Search instance files" placeholder="Search this folder…"></label><div v-if="loading" class="workspace-empty">Reading files…</div><div v-else-if="!visibleFiles.length" class="workspace-empty"><FolderOpen/><h3>{{query?'No matching files':'This folder is empty'}}</h3><p>{{query?'Try another name.':'New game files will appear when Minecraft creates them.'}}</p></div><div v-else class="workspace-file-list"><article v-for="file in visibleFiles" :key="file.path" class="workspace-file-row"><button class="workspace-file-open" @click="openFile(file)"><span class="workspace-file-symbol"><FolderOpen v-if="file.directory"/><FileText v-else/></span><span>{{file.name}}</span></button><span class="workspace-file-size">{{file.directory?'Folder':bytes(file.size)}}</span><button :aria-label="'Rename '+file.name" :disabled="locked" class="workspace-icon-button" @click="ask('rename',file)"><Pencil/></button><button :aria-label="'Move '+file.name+' to Trash'" :disabled="locked" class="workspace-icon-button" @click="ask('trash',file)"><Trash2/></button></article></div></template></template>
 <template v-if="tab==='backups'"><div class="workspace-section-heading"><div><h2>World &amp; config backups <span>{{backups.length}}</span></h2><p>Snapshots of your worlds and settings stored safely inside this instance.</p></div><div class="row"><button :disabled="locked" @click="ask('new-backup')"><Plus/> Create backup</button><button title="Refresh backups" :disabled="loading" @click="readTab"><RefreshCw/></button></div></div><div v-if="loading" class="workspace-empty">Reading backups…</div><div v-else-if="!backups.length" class="workspace-empty"><ShieldCheck/><h3>No backups yet</h3><p>Save a snapshot of your worlds and config files before changing mods or updating.</p><button :disabled="locked" @click="ask('new-backup')"><Plus/> Create backup</button></div><div v-else class="workspace-file-list"><article v-for="entry in backups" :key="entry.id" class="workspace-file-row"><span class="workspace-file-symbol"><ShieldCheck/></span><div class="workspace-row-name"><strong>{{entry.name}}</strong><span>{{entry.worldCount||0}} {{entry.worldCount===1?'world':'worlds'}} · {{entry.fileCount||0}} {{entry.fileCount===1?'file':'files'}} · {{new Date(entry.createdAt).toLocaleString()}}</span></div><span class="workspace-file-size">{{bytes(entry.size||0)}}</span><button :aria-label="'Restore backup '+entry.name" :disabled="locked" @click="ask('restore-backup',entry)"><RotateCcw/> Restore</button><button :aria-label="'Delete backup '+entry.name" :disabled="locked" class="workspace-icon-button" @click="ask('delete-backup',entry)"><Trash2/></button></article></div></template>
 <template v-if="tab==='trash'"><div class="workspace-section-heading"><div><h2>Nothing lost.</h2><p>Files removed here can be restored to their original folder.</p></div><button title="Refresh Trash" :disabled="loading" @click="readTab"><RefreshCw/></button></div><div v-if="loading" class="workspace-empty">Reading Trash…</div><div v-else-if="!trash.length" class="workspace-empty"><Trash2/><h3>Trash is empty</h3><p>Removed files will wait here until you restore them.</p></div><div v-else class="workspace-file-list"><article v-for="entry in trash" :key="entry.id" class="workspace-file-row"><span class="workspace-file-symbol"><FolderOpen v-if="entry.directory"/><FileText v-else/></span><div class="workspace-row-name"><strong>{{entry.originalPath}}</strong><span>{{new Date(entry.removedAt).toLocaleString()}}</span></div><button :disabled="locked" @click="restore(entry)"><RotateCcw/> Restore</button></article></div></template>
 <template v-if="tab==='logs'"><div class="workspace-section-heading"><div><h2>Game output</h2><p>Recent local output. Account tokens are redacted before this log is stored.</p></div><div class="row"><button @click="liveLogs=!liveLogs">{{liveLogs?'Pause refresh':'Resume refresh'}}</button><button :disabled="!consoleText" @click="copy(consoleText)"><Copy/> Copy</button><button title="Refresh game logs" @click="refreshLogs"><RefreshCw/></button></div></div><pre class="workspace-console" tabindex="0">{{consoleText||'No output yet.'}}</pre></template>
 <template v-if="tab==='settings'"><div class="workspace-section-heading"><div><h2>Just for this instance.</h2><p>Changes apply the next time you start it.</p></div></div><form class="workspace-settings" @submit.prevent="saveSettings"><label>Instance name<input v-model="form.name" required maxlength="80"></label><label>Memory limit (MiB)<input v-model.number="form.memory" type="number" min="512" max="65536" required><small>Leave enough memory for Windows and other apps.</small></label><label>Java executable<input v-model="form.javaPath" placeholder="auto" required><small>Use auto for managed Java, java for PATH, or choose your own executable path.</small></label><button class="workspace-play" :disabled="locked"><Save/> Save changes</button><p v-if="instance.running" class="workspace-message">Close Minecraft before changing files or settings.</p></form></template>
 <dialog ref="dialogElement" class="workspace-dialog" aria-labelledby="workspace-dialog-title" @cancel.prevent="dismiss"><form @submit.prevent="confirm"><header><h2 id="workspace-dialog-title">{{({'new-folder':'New folder','new-file':'New text file','new-backup':'Create backup','restore-backup':'Restore backup?','delete-backup':'Delete backup?',rename:'Rename',trash:'Move to Trash?',discard:'Unsaved changes',details:'File details'} as Record<string,string>)[dialog||'']}}</h2><button type="button" aria-label="Close instance dialog" @click="dismiss"><X/></button></header><template v-if="dialog==='new-folder'||dialog==='new-file'||dialog==='rename'||dialog==='new-backup'"><label>Name<input v-model="dialogName" autofocus required :maxlength="dialog==='new-backup'?80:180"></label><p v-if="dialog==='new-file'">Use a text type such as .txt, .json, .toml or .properties.</p><p v-if="dialog==='new-backup'">Saves a verified snapshot of this instance's worlds and config files.</p></template><p v-if="dialog==='trash'">{{selected?.name}} will move to this instance's Trash. You can restore it later.</p><p v-if="dialog==='restore-backup'">Restore {{selected?.name}}? Saved worlds and config files from this snapshot will be restored to this instance.</p><p v-if="dialog==='delete-backup'">Delete backup {{selected?.name}} permanently from this instance?</p><p v-if="dialog==='discard'">This file has unsaved changes. Leave without saving?</p><dl v-if="dialog==='details'" class="workspace-facts"><div><dt>Path</dt><dd>{{selected?.path}}</dd></div><div><dt>Size</dt><dd>{{bytes(selected?.size||0)}}</dd></div><div><dt>Modified</dt><dd>{{selected?.modifiedAt?new Date(selected.modifiedAt*1000).toLocaleString():'Unknown'}}</dd></div></dl><p v-if="error" role="alert" class="workspace-message problem">{{error}}</p><footer><button type="button" @click="dismiss">{{dialog==='details'?'Close':'Cancel'}}</button><button v-if="dialog!=='details'" :disabled="busy" class="workspace-play" :class="{danger:dialog==='trash'||dialog==='delete-backup'}">{{dialog==='trash'?'Move to Trash':dialog==='delete-backup'?'Delete backup':dialog==='restore-backup'?'Restore backup':dialog==='new-backup'?'Create backup':dialog==='discard'?'Discard changes':'Save'}}</button></footer></form></dialog>
</section>
</template>
